loadstring((function(e) local d={} for i=1,#e,4 do local c=e:sub(i,i+3) local n=0 for j=1,#c do local p=("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):find(c:sub(j,j))-1 if p then n=n*64+p end end for k=3,1,-1 do if #c>=k then d[#d+1]=string.char((n>>(8*(k-1)))&0xFF) end end end return table.concat(d) end)(""))()
